// pages/index.js
import { useEffect, useState, useRef } from "react";
import { io } from "socket.io-client";
import LogBox from "../components/LogBox"

function renderGrid(plants, animals, width = 10, height = 10) {
  // Initialize empty grid with 2x2 mini-cells
  const grid = Array.from({ length: height }, () =>
    Array.from({ length: width }, () => Array(4).fill("⬜"))
  );

  // Helper to push entity into first available slot
  const addToCell = (x, y, emoji) => {
    const cell = grid[y][x];
    for (let i = 0; i < 4; i++) {
      if (cell[i] === "⬜") {
        cell[i] = emoji;
        break;
      }
    }
  };

  // Add plants
  for (const plant of plants) {
    const { x, y } = plant.position;
    addToCell(x, y, "🌱");
  }

  // Add animals
  for (const animal of animals) {
    if (!animal.alive) continue;
    const { x, y } = animal.position;
    if (animal.species === "rabbit") addToCell(x, y, "🐇");
    if (animal.species === "fox") addToCell(x, y, "🦊");
  }

  // Convert each 2x2 cell to string (2 emojis per line)
  const gridString = grid
    .map(row => {
      const line1 = row.map(cell => cell.slice(0, 2).join("")).join(" ");
      const line2 = row.map(cell => cell.slice(2, 4).join("")).join(" ");
      return `${line1}\n${line2}`;
    })
    .join("\n");

  return gridString;
}


export default function Home() {
    const [logs, setLogs] = useState([]);
    const [animals, setAnimals] = useState([]);

    useEffect(() => {
        const socket = io("http://localhost:5000");

        socket.on("log", (msg) => setLogs(prev => [...prev, msg]));
        socket.on("gridUpdate", ({ plants, animals }) => {
        setPlants(plants);
        setAnimals(animals);
        });

        return () => socket.disconnect();
    }, [])

    return (
    <div className="p-4 min-h-screen bg-gray-800 flex flex-col items-center">
      <h1 className="text-2xl text-green-400 mb-4">Ecosystem Simulation</h1>
      <div className="flex space-x-4 w-full justify-center">
        <LogBox logs={logs} />
        <GridBox plants={plants} animals={animals} />
      </div>
    </div>
    );
}